import {TRAIN_ROUTES,countdownRemaining,formatCountdown} from './game-ui.js';
import {teamColorHTML,bindTeamColor,membersHTML,bindMembers} from './team-editor.js';
import {parseRosterCSV} from './roster.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,boot=null,page='play',adminLogin=false,socket=null,reconnect=null,refreshing=false,googleLoading=null,selectedPlace=null,visibleFeed=20,connection='Connecting',clockOffset=0;
let preservingMap=false,selectedTeam=null,tickerPaused=false,clockServer=Date.now(),clockAt=performance.now();
const modal=$('#modal');
const team=id=>state?.teams.find(t=>t.id===id);
const venue=id=>state?.venues.find(v=>v.id===id);
const challenge=id=>state?.challenges.find(c=>c.id===Number(id));
const stamp=s=>new Date(s).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const badge=(s,label=s)=>`<span class="badge ${esc(s)}">${esc(label)}</span>`;
const tag=id=>{const t=team(id);return t?`<span class="team-tag"><i class="team-dot" style="background:${/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#999'}"></i>${esc(t.name)}</span>`:'Unclaimed';};
const photo=id=>`/api/media/${encodeURIComponent(id)}`;
const options=(items,value)=>items.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('');
function toast(s){const el=$('#toast');el.textContent=s;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body&&!(body instanceof FormData)?{'Content-Type':'application/json'}:{},body:body?body instanceof FormData?body:JSON.stringify(body):undefined,credentials:'same-origin'});let d;try{d=await r.json();}catch{throw new Error('Server unavailable. Check your connection and try again.');}if(!r.ok)throw Object.assign(new Error(d.error||'Request failed'),d,{status:r.status});return d;}
function setState(data){if(state?.settings.id!==data.settings.id){selectedTeam=null;territory=null;}state=data;clockServer=data.serverTime||Date.now();clockAt=performance.now();clockOffset=clockServer-Date.now();if(selectedTeam&&!team(selectedTeam))selectedTeam=null;}
function updateClock(){if(!state)return;const g=state.settings;let ms=g.timer_elapsed_ms;if(g.timer_started_at!==null)ms+=Math.max(0,Date.now()+clockOffset-g.timer_started_at);const seconds=Math.floor(ms/1000),value=g.started_at===null?'Not started':`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;document.querySelectorAll('[data-game-clock]').forEach(el=>el.textContent=value);}
setInterval(updateClock,1000);
function logo(settings){return `<div class="brand"><img src="${settings?.logo?photo(settings.logo):'/branding/logo.png'}" alt="Battle for New York" data-logo><div class="brand-fallback" hidden><span class="roundel">NY</span><div class="brand-title">Battle for<br>New York</div></div></div>`;}
function header(){const settings=state?.settings||boot?.settings;$('#header').innerHTML=logo(settings)+(state?`<div class="header-tools"><div class="small muted">${esc(state.settings.name)}</div><div class="clock-label">Game clock <span class="game-clock" data-game-clock></span></div><div class="connection ${connection==='Live'?'online':''}" id="connection"><span class="live-dot"></span>${esc(connection)}</div><button class="ghost" data-action="logout">Sign out</button></div>`:`<span class="eyebrow">Claim your city</span>`);const img=$('[data-logo]');img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling.hidden=false;});updateClock();}
function statusConnection(label){connection=label;const c=$('#connection');if(c){c.className='connection '+(label==='Live'?'online':'');c.innerHTML=`<span class="live-dot"></span>${esc(label)}`;}}
async function refresh(){if(refreshing||!state)return;refreshing=true;const previous=state.settings;try{setState(await api('state'));header();if(!modal.open){if(page==='play'&&$('#play-list')&&previous.id===state.settings.id&&previous.phase===state.settings.phase)renderPlayList();else if(page==='scoreboard'&&previous.id===state.settings.id&&$('#territory-map'))refreshScoreboard();else renderPage();}}catch(e){if(e.status===401){state=null;disconnect();await loginScreen();}else statusConnection('Reconnecting');}finally{refreshing=false;}}
function disconnect(){clearTimeout(reconnect);if(socket){socket.onclose=null;socket.close();socket=null;}}
function connect(){disconnect();if(!state)return;socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/live`);socket.onopen=()=>{statusConnection('Live');refresh();};socket.onmessage=()=>refresh();socket.onerror=()=>statusConnection('Reconnecting');socket.onclose=()=>{statusConnection('Reconnecting');reconnect=setTimeout(()=>{if(state)connect();},3500);};}
setInterval(()=>{if(state&&!document.hidden)refresh();},20000);
window.addEventListener('online',()=>{if(state){refresh();connect();}});
window.addEventListener('offline',()=>statusConnection('Offline — reconnect to submit'));
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state)refresh();});
function nav(){const tabs=[['play','◎','Play'],['scoreboard','▤','Scoreboard'],['feed','▧','Feed'],['rules','☷','Rules']];if(state.me.role==='admin')tabs.push(['admin','⚙','Admin']);$('#nav').innerHTML=tabs.map(([id,icon,title])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${title}</button>`).join('');}
function hero(kicker,title,description,number){return `<section class="hero"><div><div class="eyebrow">${esc(kicker)}</div><h1>${title}</h1><p class="muted">${esc(description)}</p></div>${number!==undefined?`<div class="hero-number">${number}<span>Points</span></div>`:''}</section>`;}
async function loginScreen(){
 boot=await api('bootstrap');header();$('#nav').innerHTML='';
 $('#main').innerHTML=`<section class="login"><div class="eyebrow">New York is the playing field</div><h1>Your city.<br>Your territory.</h1><p class="muted">Find your next stop. Complete the challenge.<br>Make it yours.</p><form id="login" class="panel accent"><h2>${adminLogin?'Game control':'Join your team'}</h2>${adminLogin?'':`<label for="login-game">Game</label><select id="login-game" required><option value="">Choose a game</option>${options(boot.games.map(g=>[g.id,g.name]),boot.games.length===1?boot.games[0].id:'')}</select><label for="login-team">Team</label><select id="login-team" required><option value="">Choose your team</option></select>`}<label for="passcode">${adminLogin?'Admin password':'Team passcode'}</label><input id="passcode" type="password" required autocomplete="current-password"><p class="error" id="login-error" role="alert"></p><button class="primary full" type="submit">${adminLogin?'Open admin':'Let’s go →'}</button>${!boot.games.length&&!adminLogin?'<p class="info">No games are enabled yet. Your admin will open the lobby when it’s ready.</p>':''}</form><button class="login-switch" data-action="switch-login">${adminLogin?'← Back to team login':'Game admin? Sign in here'}</button>${adminLogin?'':'<button class="login-switch" data-action="refresh-login">Refresh available games</button>'}</section>`;
 if(!adminLogin){const choose=()=>{$('#login-team').innerHTML='<option value="">Choose your team</option>'+options(boot.teams.filter(t=>t.game_id===$('#login-game').value).map(t=>[t.id,t.name]));};$('#login-game').onchange=choose;choose();}
 $('#login').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{await api('login',{admin:adminLogin,gameId:$('#login-game')?.value,teamId:$('#login-team')?.value,passcode:$('#passcode').value});setState(await api('state'));page=state.me.role==='admin'?'admin':'play';header();renderPage();connect();}catch(e){$('#login-error').textContent=e.message;}finally{btn.disabled=false;}};
}
function phaseNotice(){const p=state.settings.phase,messages={draft:'This game is a draft. Enable it in Admin to open the lobby.',lobby:'The lobby is open. Play begins when the admin starts the timer.',paused:'The game and timer are paused.',ended:'The game has ended. These are the final results.'};return p==='live'?'':`<div class="notice">${messages[p]||'The game is not running.'} ${state.me.role==='admin'?'':'You can browse the scoreboard and feed.'}</div>`;}
function renderPage(){const previousFilter=$('#venue-filter')?.value||'';nav();const main=$('#main');if(page==='play'){main.innerHTML=hero(state.me.name,'Make your<br>next move.','Claim a bar. Finish your challenge. Lock it down.',team(state.me.id)?.score)+`<div id="countdown-slot"></div><div id="phase-notice">${phaseNotice()}</div>`+(state.me.role==='team'?`<section class="panel accent"><div class="row between"><h2>Find your bar</h2><span class="roundel" aria-hidden="true">↗</span></div><p class="muted small">Search by venue name and check the address.</p><div class="searchbox" id="place-search"></div><div id="place-result"></div></section>`:`<div class="notice">You’re signed in as admin. Team accounts are used to claim bars.</div>`)+`<div id="play-list"></div>`;renderPlayList();if(state.me.role==='team')initPlaces();}
else if(page==='scoreboard'){main.innerHTML=hero('The battle so far','City standings.','Claim for 1 point. Lock for 1 more. Every locked bar is worth 2.')+phaseNotice()+`<div id="countdown-slot"></div><div class="scoreboard-stack">${activityTicker()}<div class="grid scoreboard-layout"><section class="panel"><h2>The leaderboard</h2>${state.teams.map((t,i,all)=>`<div class="rank-row"><span class="rank">${all.findIndex(x=>x.score===t.score)+1}</span><div class="rank-body"><button class="team-select ghost" data-action="select-team" data-id="${esc(t.id)}" aria-pressed="${selectedTeam===t.id}">${tag(t.id)}</button><div class="muted small">${state.venues.filter(v=>v.owner===t.id&&v.status==='locked').length} locked · ${state.venues.filter(v=>v.owner===t.id&&v.status!=='locked').length} unlocked${t.adjustment?` · ${t.adjustment>0?'+':''}${t.adjustment} adjustment`:''}</div></div><span class="score">${t.score}</span></div>`).join('')||'<p class="muted">No teams yet.</p>'}</section><section class="panel territory-panel"><h2>Live Territory</h2>${territorySummary()}<p class="muted small">Pins show the current owner. Tap a pin for details.</p><div id="territory-map" class="territory-map" aria-label="Map of claimed bars"></div><p id="map-status" class="info" role="status">Loading map…</p><button class="ghost" data-action="fit-map">Show all bars</button></section>${drinkersHTML()}<section class="venue-panel"><h2>On the map</h2><p class="muted small">Every bar in play, and who owns it.</p><input class="filter" id="venue-filter" placeholder="Filter bars or teams…" aria-label="Filter bars or teams"><div id="venue-list"></div></section></div></div>`;$('#venue-filter').value=previousFilter;renderVenues();$('#venue-filter').oninput=renderVenues;renderCountdown();if(!preservingMap)initTerritoryMap();}
else if(page==='feed'){main.innerHTML=`<div class="feed">${hero('From the streets','The city feed.','Every claim. Every challenge. Every steal.')}<div id="feed-list">${feedHTML()}</div></div>`;}
else if(page==='rules'){main.innerHTML=hero('Know the game','How we play.','Your pocket guide to Battle for New York.')+`<section class="panel"><h2>The website rules</h2><div class="stack"><p><strong>Claim:</strong> finish the required drinks, choose the venue and upload a team photo. A successful claim earns one point.</p><p><strong>Lock:</strong> select the challenge you physically drew and mark it completed. Locking adds one more point and protects the bar. A locked bar is worth two points.</p><p><strong>Fail or veto:</strong> record the card and outcome. You keep the point, but the bar opens to steals. Your team cannot retry.</p><p><strong>Steal:</strong> start an attempt at an open bar with a team photo. Complete your challenge to transfer ownership and lock the bar for two points. Steals are only available after the owner fails or vetoes. If you fail, the old owner keeps it. First successful lock wins.</p><p><strong>Timing:</strong> the admin opens the lobby separately from starting the game clock. Claims and outcomes are enabled only during play. Individual challenge timing and curses are managed outside the website.</p><p><strong>Connection:</strong> wait for a success message before assuming a claim or lock is recorded. Claims require an internet connection.</p></div></section><details class="panel"><summary>Original rules & how-to-play</summary><img class="rules-img" src="/rules/rules.png" alt="Battle for New York original rules"><img class="rules-img" src="/rules/how-to-play.png" alt="Battle for New York how to play"></details>`;}
else if(page==='admin')renderAdmin();}
function refreshScoreboard(){
 const mapPanel=$('#territory-map').closest('section'), saved=territory,oldTicker=$('#activity-ticker');
 mapPanel.remove();preservingMap=true;renderPage();preservingMap=false;
 const placeholder=$('#territory-map').closest('section');placeholder.replaceWith(mapPanel);
 const summary=mapPanel.querySelector('.territory-summary');if(summary)summary.outerHTML=territorySummary();
 const newTicker=$('#activity-ticker');if(oldTicker&&newTicker&&oldTicker.dataset.signature===newTicker.dataset.signature)newTicker.replaceWith(oldTicker);
 territory=saved;syncTerritoryMap();
}
function renderPlayList(){renderCountdown();const score=$('.hero-number');if(score)score.innerHTML=`${team(state.me.id)?.score||0}<span>Points</span>`;if($('#phase-notice'))$('#phase-notice').innerHTML=phaseNotice();const mine=state.attempts.filter(a=>a.team_id===state.me.id),pending=mine.filter(a=>a.status==='pending');$('#play-list').innerHTML=`<div class="section-label"><h2>Your Active Stops</h2>${badge('pending',`${pending.length} active`)}</div>${pending.map(a=>attemptHTML(a)).join('')||'<div class="empty"><strong>No active challenges</strong>Search for a bar above to get started.</div>'}<div class="section-label"><h2>Open to Steal</h2></div>${state.venues.filter(v=>v.status==='open'&&v.owner!==state.me.id&&!mine.some(a=>a.venue_id===v.id)).map(v=>venueHTML(v,true)).join('')||'<p class="muted">No eligible bars right now.</p>'}<div class="section-label"><h2>Your Previous Stops</h2></div>${mine.filter(a=>a.status!=='pending').map(a=>attemptHTML(a)).join('')||'<p class="muted">Your finished attempts will appear here.</p>'}`;}
function attemptHTML(a){const v=venue(a.venue_id);return `<article class="venue"><div class="row between"><h3>${esc(v?.name)}</h3>${badge(a.status,a.status==='pending'?(a.kind==='steal'?'Steal in progress':'Challenge pending'):a.status)}</div><p class="muted small">${esc(v?.address)}</p>${a.challenge?`<p class="small">#${a.challenge} · ${esc(challenge(a.challenge)?.name)}</p>`:''}${a.status==='pending'&&state.settings.phase==='live'?`<button class="primary full" data-action="outcome" data-id="${a.id}">Record challenge outcome →</button>`:`<p class="small muted">Current owner: ${tag(v?.owner)} · ${esc(v?.status)}</p>`}</article>`;}
function venueHTML(v,steal=false){return `<article class="venue"><div class="row between"><h3>${esc(v.name)}</h3>${badge(v.status,v.status==='open'?'Open to steal':v.status)}</div><p class="muted small">${esc(v.address)}</p><div class="row between wrap">${tag(v.owner)}<a class="small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v.name)}&query_place_id=${encodeURIComponent(v.id)}" target="_blank" rel="noopener noreferrer">Directions ↗</a></div>${steal&&state.me.role==='team'&&state.settings.phase==='live'?`<button class="primary full" style="margin-top:15px" data-action="steal" data-id="${esc(v.id)}">Start a steal →</button>`:''}</article>`;}
function renderVenues(){const q=$('#venue-filter').value.toLowerCase();$('#venue-list').innerHTML=state.venues.filter(v=>(!selectedTeam||v.owner===selectedTeam)&&`${v.name} ${v.address} ${team(v.owner)?.name||''}`.toLowerCase().includes(q)).map(v=>venueHTML(v)).join('')||'<div class="empty">No bars found.</div>';}
function feedHTML(){if(!state.attempts.length)return '<div class="empty"><strong>The city is quiet… for now.</strong>The first team photo will appear here.</div>';return state.attempts.slice(0,visibleFeed).map(a=>{const v=venue(a.venue_id),imgs=[a.photo,a.completion_photo].filter(Boolean);return `<article class="post"><div class="post-head"><div><strong>${tag(a.team_id)}</strong><div class="small muted">${stamp(a.created)} ET</div></div>${badge(a.status,a.status==='pending'?(a.kind==='steal'?'Attempting steal':'Claimed'):a.status==='completed'?'Locked':a.status)}</div>${imgs.length?`<div class="${imgs.length>1?'photo-pair':''}">${imgs.map(id=>`<a href="${photo(id)}" target="_blank" rel="noopener"><img loading="lazy" class="post-photo" src="${photo(id)}" alt="${esc(team(a.team_id)?.name)} at ${esc(v?.name)}"></a>`).join('')}</div>`:'<div class="empty">No photo attached</div>'}<div class="post-body"><h3>${esc(v?.name)}</h3><p class="muted small">${esc(v?.address)}</p>${a.challenge?`<button class="ghost" data-action="card" data-id="${a.challenge}">#${a.challenge} · ${esc(challenge(a.challenge)?.name)} ↗</button>`:''}<p class="small muted" style="margin-top:12px">${a.kind==='steal'?'Steal attempt':'Original claim'} · Current owner: ${tag(v?.owner)}</p>${drankHTML(a.id)}${state.me.role==='admin'?`<div class="row wrap"><button data-action="edit-attempt" data-id="${a.id}">Correct card / outcome</button>${imgs.map(id=>`<button class="danger" data-action="remove-photo" data-id="${id}">Remove ${id===a.photo?'claim':'completion'} photo</button>`).join('')}</div>`:''}</div></article>`;}).join('')+(state.attempts.length>visibleFeed?'<button class="full" data-action="more-feed">Load more</button>':'');}
async function loadGoogle(){
 if(window.google?.maps?.places)return;
 if(!state.googleKey||state.googleKey.startsWith('REPLACE_'))throw new Error('Google Maps is not configured. Add GOOGLE_MAPS_BROWSER_KEY to the game Worker.');
 if(!googleLoading)googleLoading=new Promise((resolve,reject)=>{
  const script=document.createElement('script');
  const fail=()=>{clearTimeout(timer);script.remove();googleLoading=null;reject(new Error('Google Maps could not load. Check your connection, API key and billing.'));};
  const timer=setTimeout(fail,20000);
  window.bfnyMapsReady=()=>{clearTimeout(timer);resolve();};
  script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(state.googleKey)}&libraries=places&v=weekly&loading=async&callback=bfnyMapsReady`;
  script.onerror=fail;document.head.append(script);
 });
 return googleLoading;
}
async function initPlaces(){const host=$('#place-search');host.innerHTML='<p class="info">Loading venue search…</p>';try{await loadGoogle();if(!host.isConnected)return;host.innerHTML='';const widget=new google.maps.places.PlaceAutocompleteElement({includedRegionCodes:['us'],locationBias:{north:40.93,south:40.48,east:-73.68,west:-74.26}});widget.setAttribute('aria-label','Search bars and restaurants');host.append(widget);widget.addEventListener('gmp-select',async({placePrediction})=>{try{const p=placePrediction.toPlace();await p.fetchFields({fields:['id','displayName','formattedAddress','location']});if(p.location)placeLocations.set(p.id,p.location.toJSON());selectedPlace={placeId:p.id,name:p.displayName,address:p.formattedAddress||''};const v=venue(p.id),old=state.attempts.find(a=>a.venue_id===p.id&&a.team_id===state.me.id);$('#place-result').innerHTML=`<div class="venue" style="margin-top:16px"><h3>${esc(p.displayName)}</h3><p class="muted small">${esc(p.formattedAddress)}</p>${v?`${badge(v.status)} ${tag(v.owner)}`:''}<button class="primary full" data-action="claim-selected" style="margin-top:14px" ${state.settings.phase!=='live'||old||v&&(v.status==='locked'||v.status==='claimed')?'disabled':''}>${old?'Your team already attempted this bar':v?.status==='locked'?'Already locked':v?.status==='claimed'?'Challenge in progress':v?.status==='open'?'Start a steal →':'Claim this bar →'}</button></div>`;}catch(e){toast(e.message);}});widget.addEventListener('gmp-error',()=>toast('Google search error. Ask the admin to check the API key and billing.'));}catch(e){host.innerHTML=`<p class="error">${esc(e.message)}</p>`;}}
function showModal(title,html){const preview=$('#photo-preview');if(preview?.dataset.object)URL.revokeObjectURL(preview.dataset.object);$('#modal-body').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close ghost" data-action="close" aria-label="Close">×</button></div>${html}`;if(!modal.open)modal.showModal();}
function bindForm(run){const f=$('#modal form');f.addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter,data=new FormData(f,e.submitter);btn.disabled=true;const err=$('#form-error');err.textContent='';try{await run(data);modal.close();await refresh();toast('Saved.');}catch(e){if(e.code==='OUTCOME_REQUIRED'){await refresh();reportRequiredDialog({id:e.attemptId,name:e.venueName});}else err.textContent=e.message;}finally{btn.disabled=false;}});}
const formEnd=(label='Save')=>`<p id="form-error" class="error" role="alert"></p><div class="dialog-actions"><button type="button" class="ghost" data-action="close">Cancel</button><button class="primary" type="submit">${label}</button></div></form>`;
function uploadHTML(){return `<div class="upload-controls row"><label class="button ghost" for="gallery">▧ Choose photo</label><input class="file-input" id="gallery" type="file" accept="image/*"><label class="button ghost" for="camera">◎ Take photo</label><input class="file-input" id="camera" type="file" accept="image/*" capture="environment"></div><img id="photo-preview" class="photo-preview" hidden alt="Selected photo preview"><p class="info" id="upload-status"></p>`;}
function bindUpload(kind='photo'){
  let file=null,uploaded=null;
  for(const id of ['gallery','camera'])$('#'+id).onchange=async e=>{const original=e.target.files[0];if(!original)return;uploaded=null;file=null;$('#upload-status').textContent='Preparing image…';try{const object=URL.createObjectURL(original);try{const img=new Image();img.src=object;await img.decode();const scale=Math.min(1,(kind==='logo'?1600:1800)/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);file=await new Promise(resolve=>canvas.toBlob(resolve,kind==='logo'?'image/png':'image/jpeg',.82));checkFile(file);const preview=$('#photo-preview');if(preview.dataset.object)URL.revokeObjectURL(preview.dataset.object);preview.dataset.object=URL.createObjectURL(file);preview.src=preview.dataset.object;preview.hidden=false;$('#upload-status').textContent=`Ready · ${Math.round(file.size/1024)} KB`;}finally{URL.revokeObjectURL(object);}}catch{file=null;$('#upload-status').textContent='Could not read this photo. Try a JPEG/PNG or take a new photo. On iPhone, a screenshot also works.';}};
  return async(required=false)=>{if(uploaded)return uploaded;if(!file){if(required)throw new Error('Choose or take a team photo first.');return null;}$('#upload-status').textContent='Uploading…';const data=new FormData();data.append('file',file,kind==='logo'?'logo.png':'photo.jpg');data.append('kind',kind);uploaded=(await api('upload',data)).id;$('#upload-status').textContent='Photo uploaded.';return uploaded;};
}
function checkFile(file){if(!file||file.size>8*1024*1024)throw new Error('Image too large.');}
function reportRequiredDialog(a){showModal('Report your previous challenge',`<p>You haven’t reported your challenge outcome from <strong>${esc(a.name||venue(a.venue_id)?.name)}</strong>. Report it before claiming another bar.</p><div class="dialog-actions"><button class="ghost" data-action="close">Close</button><button class="primary" data-action="outcome" data-id="${esc(a.id)}">Report outcome →</button></div>`);}
function claimDialog(p){
 const pending=state.attempts.find(a=>a.team_id===state.me.id&&a.status==='pending');if(pending){reportRequiredDialog(pending);return;}
 const existing=venue(p.placeId),stealing=existing?.owner,members=state.members.filter(m=>m.team_id===state.me.id&&m.active);
 showModal(stealing?'Start a steal':'Claim this bar',`<form><h3>${esc(p.name)}</h3><p class="muted small">${esc(p.address)}</p><div class="notice">${stealing?'The current owner keeps their point until you complete your challenge. A successful steal locks this bar for 2 points.':'Confirm your team has met the claiming requirement. This photo and claim will appear in the team feed.'}</div>${members.length?`<fieldset class="member-list"><legend>Who had a drink here?</legend><p class="info">Each selected person gets one drink recorded at this bar.</p>${members.map(m=>`<label class="member-choice"><input type="checkbox" name="drinkers" value="${esc(m.id)}"> ${esc(m.name)}</label>`).join('')}</fieldset>`:'<p class="info">Your admin hasn’t added a team roster yet.</p>'}${uploadHTML()}<label class="row"><input type="checkbox" required> We are at this venue and have met the claiming requirement.</label>${formEnd(stealing?'Start attempt':'Claim +1 point')}`);
 const upload=bindUpload();bindForm(async form=>{const img=await upload(true);await api('claim',{...p,photo:img,drinkers:form.getAll('drinkers')});});
}
function pickerHTML(){return `<label for="challenge-query">Which challenge did you draw?</label><input id="challenge-query" placeholder="Search title or card number…" autocomplete="off"><input type="hidden" id="challenge-id"><div class="challenge-results" id="challenge-results"></div><img id="challenge-preview" class="challenge-preview" hidden alt="Selected challenge card">`;}
function bindPicker(initial){const query=$('#challenge-query'),list=$('#challenge-results');const draw=()=>{const q=query.value.toLowerCase().replace(/^#/,''),cards=state.challenges.filter(c=>`${c.id} ${c.name} ${c.aliases}`.toLowerCase().includes(q));list.innerHTML=cards.map(c=>`<button type="button" class="challenge-option ${Number($('#challenge-id').value)===c.id?'selected':''}" data-pick="${c.id}"><img loading="lazy" src="${c.image}" alt=""><span><strong>#${c.id}</strong> · ${esc(c.name)}</span></button>`).join('')||'<p class="info">No matching cards.</p>';};query.oninput=draw;list.onclick=e=>{const btn=e.target.closest('[data-pick]');if(btn)select(Number(btn.dataset.pick));};function select(id){const c=challenge(id);if(!c)return;$('#challenge-id').value=id;query.value=`${id} ${c.name}`;$('#challenge-preview').src=c.image;$('#challenge-preview').hidden=false;draw();}if(initial)select(initial);else draw();}
function outcomeDialog(id){const a=state.attempts.find(a=>a.id===id);if(!a)return;showModal('Record your challenge',`<form><h3>${esc(venue(a.venue_id)?.name)}</h3>${pickerHTML()}<label for="outcome">Outcome</label><select id="outcome" required><option value="">Choose an outcome</option><option value="completed">Completed — lock for +1 point</option><option value="failed">Failed — no retry</option><option value="vetoed">Vetoed — no retry</option></select><label>Extra photo (optional)</label>${uploadHTML()}<p class="info">Failure or veto is final for your team at this bar. Ask the admin to correct mistakes.</p>${formEnd('Confirm outcome')}`);bindPicker();const upload=bindUpload();bindForm(async()=>{const c=Number($('#challenge-id').value);if(!c)throw new Error('Select the challenge card from the results.');await api('outcome',{id,status:$('#outcome').value,challenge:c,photo:await upload()});});}
function drinkersHTML(){
 const all=state.drinkers,leaders=all.filter(m=>m.drinks>0),rank=m=>all.findIndex(x=>x.drinks===m.drinks)+1;
 const card=(m,i)=>{if(!m)return `<div class="podium-place place-${i+1} empty-place"><span class="podium-rank">${i+1}</span><span class="muted small">—</span></div>`;const r=rank(m),name=state.podiumNames[r-1];return `<div class="podium-place place-${i+1}" style="--team-color:${team(m.team_id)?.color||'#999'}"><span class="podium-rank">${r}</span>${name&&name!==String(r)?`<strong class="podium-title">${esc(name)}</strong>`:''}<strong class="drinker-name">${esc(m.name)}</strong><span class="small muted">${tag(m.team_id)}</span><span class="drink-count">${m.drinks}<small>${m.drinks===1?'drink':'drinks'}</small></span></div>`;};
 return `<section class="panel drinker-panel"><h2>Drinkers’ standings</h2><p class="muted small">One drink per person, per bar. Equal counts share a rank.</p><div class="podium">${[1,0,2].map(i=>card(leaders[i],i)).join('')}</div>${!leaders.length?'<p class="info">The first recorded drinks will appear here.</p>':''}${all.filter(m=>!leaders.slice(0,3).some(l=>l.id===m.id)).map(m=>`<div class="rank-row drinker-row"><span class="rank">${rank(m)}</span><div class="rank-body"><strong>${esc(m.name)}</strong><div class="muted small">${tag(m.team_id)}</div></div><span class="score">${m.drinks}</span></div>`).join('')}</section>`;
}
function drankHTML(attemptId){const names=state.drinks.filter(d=>d.attempt_id===attemptId).map(d=>state.members.find(m=>m.id===d.member_id)?.name).filter(Boolean);return names.length?`<p class="small muted">Drank here: ${names.map(esc).join(', ')}</p>`:'';}
function gameControlsHTML(){const p=state.settings.phase,actions={draft:[['enable','Enable game']],lobby:[['start','Start timer & play']],live:[['pause','Pause game & timer'],['end','End game']],paused:[['resume','Resume game & timer'],['end','End game']],ended:[['resume','Reopen & resume timer']]};return `<div class="game-actions">${actions[p].map(([id,label],i)=>`<button class="${i===0?'primary':'ghost'}" data-action="game-lifecycle" data-id="${id}">${label}</button>`).join('')}</div>`;}
function renderAdmin(){
 const g=state.settings,help={draft:'Prepare teams and rosters now. Enabling opens team logins without starting the timer.',lobby:'Teams can sign in and browse. Start the timer separately to open claims and outcomes.',live:'Claims and outcomes are open. The game clock is running.',paused:'Team submissions and the game clock are paused.',ended:'Results are saved. The game clock is stopped.'};
 $('#main').innerHTML=hero('Game control','Run the city.','Manage teams, fix mistakes, and keep the game moving.')+`<section class="panel"><label for="admin-game">Saved games</label><div class="row game-picker"><select id="admin-game">${options(state.games.map(g=>[g.id,`${g.name} · ${g.phase}`]),g.id)}</select><button data-action="new-game">+ New draft</button></div></section><section class="panel accent"><div class="row between wrap"><h2>${esc(g.name)}</h2>${badge(g.phase)}</div><p class="info">${help[g.phase]}</p><p class="admin-clock"><span class="muted small">Game clock</span> <span data-game-clock></span></p>${gameControlsHTML()}<div class="admin-actions"><button data-action="settings">Game & logo settings</button><button data-action="countdown">Countdown & final stop</button><button data-action="new-team">+ Create team</button><button data-action="import-roster">Import teams & members</button><button data-action="podium-names">Podium nicknames</button><button data-action="adjust">Adjust a score</button><button class="danger" data-action="reset-game">Reset this game</button></div></section><div class="grid"><section class="panel"><h2>Teams</h2>${state.teams.map(t=>`<div class="rank-row"><div class="rank-body"><strong>${tag(t.id)}</strong><p class="small muted">${t.active?'Login enabled':'Login disabled'} · ${state.members.filter(m=>m.team_id===t.id&&m.active).length} members · ${t.score} points</p></div><div class="row"><button class="ghost" data-action="edit-team" data-id="${t.id}">Edit</button><button class="danger" data-action="remove-team" data-id="${t.id}">Remove</button></div></div>`).join('')||'<p class="muted">Create a team or import your roster above.</p>'}</section><section class="panel"><h2>Venue corrections</h2><p class="info">Change ownership, reopen an attempt, or undo a claim. Every correction is logged.</p>${state.venues.map(v=>`<div class="history-item"><div class="row between"><div><strong>${esc(v.name)}</strong><p class="small muted">${tag(v.owner)} · ${esc(v.status)}</p></div><button class="ghost" data-action="edit-venue" data-id="${esc(v.id)}">Edit</button></div></div>`).join('')||'<p class="muted">Venues appear after the first claim.</p>'}</section></div><details class="panel" style="margin-top:22px"><summary>Recent admin & game history</summary>${state.audit.map(a=>`<div class="history-item"><strong>${esc(a.action)}</strong><p class="small muted">${stamp(a.created)} ET</p><div class="audit">${esc(a.detail)}</div></div>`).join('')}</details>`;
 $('#admin-game').onchange=async e=>{const select=e.target;select.disabled=true;try{await api('admin/select-game',{id:select.value});await refresh();}catch(e){toast(e.message);select.disabled=false;}};updateClock();
}
function newGameDialog(){showModal('New game draft',`<form><label for="game-name">Game name</label><input id="game-name" required maxlength="80" placeholder="Battle for New York"><p class="info">Save teams, colours, passcodes and rosters in this draft. Enable it later to open the lobby.</p>${formEnd('Create draft')}`);bindForm(()=>api('admin/game',{name:$('#game-name').value}));}
